def assign(section,numbers,ids):
 for part in numbers.split(','):
  if '-' in part:
   a,b=map(int,part.split('-'));ns=range(a,b+1)
  else:ns=[int(part)]
  for n in ns:maps[section+'-'+str(n)]=ids.split(',')
